import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "tools"))

from common import get_path, isoformat_z, parse_timestamp


class TimestampTests(unittest.TestCase):
    def test_z_timestamp_has_utc_offset(self):
        parsed = parse_timestamp("2026-10-01T09:20:00Z")
        self.assertEqual(parsed.isoformat(), "2026-10-01T09:20:00+00:00")

    def test_naive_timestamp_is_rejected(self):
        with self.assertRaisesRegex(ValueError, "timezone"):
            parse_timestamp("2026-10-01T09:20:00")

    def test_invalid_timestamp_is_rejected(self):
        with self.assertRaisesRegex(ValueError, "invalid ISO"):
            parse_timestamp("next Tuesday")

    def test_offset_is_preserved(self):
        parsed = parse_timestamp("2026-10-05T08:00:00-04:00")
        self.assertEqual(isoformat_z(parsed), "2026-10-05T08:00:00-04:00")


class PathTests(unittest.TestCase):
    def test_absent_differs_from_null(self):
        record = {"present_null": None, "nested": {"value": 3}}
        self.assertEqual(get_path(record, "missing"), (False, None))
        self.assertEqual(get_path(record, "present_null"), (True, None))
        self.assertEqual(get_path(record, "nested.value"), (True, 3))
        self.assertEqual(get_path(record, "nested.value.deeper"), (False, None))


if __name__ == "__main__":
    unittest.main()

